package com.zc.agent.registry.modules.tool.controller;import com.zc.agent.registry.common.response.ApiResponse;import com.zc.agent.registry.modules.tool.dto.ToolContractRequests.*;import com.zc.agent.registry.modules.tool.service.ToolContractService;import com.zc.agent.registry.security.SecurityUser;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
/** Tool 输入 Contract 版本和样例回归 API。 */@RestController @RequestMapping("/api/registry/tools") public class ToolContractController{private final ToolContractService s;public ToolContractController(ToolContractService s){this.s=s;}@GetMapping("/{toolId}/contracts")public ApiResponse<List<Map<String,Object>>>list(@PathVariable Long toolId){return ApiResponse.success(s.list(toolId));}@PostMapping("/{toolId}/contracts")public ApiResponse<Void>create(@PathVariable Long toolId,@Valid@RequestBody ContractRequest r,Authentication a){s.create(toolId,r,user(a));return ApiResponse.success(null);}@GetMapping("/contracts/{id}/cases")public ApiResponse<List<Map<String,Object>>>cases(@PathVariable Long id){return ApiResponse.success(s.cases(id));}@PostMapping("/contracts/{id}/cases")public ApiResponse<Void>add(@PathVariable Long id,@Valid@RequestBody TestCaseRequest r,Authentication a){s.addCase(id,r,user(a));return ApiResponse.success(null);}@PostMapping("/contracts/{id}/publish")public ApiResponse<Map<String,Object>>publish(@PathVariable Long id){return ApiResponse.success(s.publish(id));}private SecurityUser user(Authentication a){return(SecurityUser)a.getPrincipal();}}
